import {rank} from './search.js';
import {finder,mountFinderNavigation,moePage,routingPage,dfsPage,mountDfs} from './experience.js';
const catalog = await fetch('catalog.json').then(r => r.json());
const notes = catalog.notes.filter(n => !n.draft && !n.unlisted && n.tracked && !n.navigationPage);
notes.push({slug:'ai/architectures/moe',prototype:true,title:'Mixture of Experts',description:'A main explainer connecting sparse architecture, expert routing, load balancing, and training stability.',topic:'ai',tags:['moe','mixture of experts'],date:null});
const params = new URLSearchParams(location.search);
const design = ['observatory','editorial','lab'].includes(params.get('design')) ? params.get('design') : null;
const view = params.get('view') || 'home';
const app = document.querySelector('#app');
const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const href = (v, d=design) => `?design=${d}&view=${v}`;
const previewViews={'math/probability/entropy':'note','ai/architectures/moe':'moe','ai/training/optimization/moe-routing-and-load-balancing':'routing','interview-prep/neetcode-roadmap/trees':'dfs'};
const noteHref = n => previewViews[n.slug] ? href(previewViews[n.slug]) : `https://naatyu.github.io${n.route}`;
const external = n => previewViews[n.slug] ? '' : 'target="_blank" rel="noopener"';
const label = topic => ({ai:'AI & learning',math:'Mathematics',systems:'Systems',algorithms:'Algorithms','interview-prep':'Interview prep',programming:'Programming',security:'Security',tooling:'Tools'}[topic] || topic);
const date = n => n.date ? new Date(n.date + 'T12:00:00Z').toLocaleDateString('en-GB',{month:'short',day:'2-digit',year:'numeric',timeZone:'UTC'}) : 'Undated';
const latest = [...notes].sort((a,b) => (b.date || '').localeCompare(a.date || '') || a.title.localeCompare(b.title)).slice(0,3);
const arrow = '<span aria-hidden="true">↗</span>';

function header() {
  return `<header class="site-header"><a class="wordmark" href="${href('home')}">${design === 'lab' ? 'n / l' : 'Nathan Laoué'}<span>${design === 'editorial' ? 'A working atlas' : 'RESEARCH / NOTES / CODE'}</span></a><nav aria-label="Main navigation"><a ${view==='home'?'aria-current="page"':''} href="${href('home')}">Home</a><a ${view==='atlas'?'aria-current="page"':''} href="${href('atlas')}">Atlas</a><a href="${href('home')}#projects">Projects</a><button class="search-trigger" data-search>Search <kbd>⌘ K</kbd></button></nav></header>`;
}
function footer() {
  return `<footer><span>Nathan Laoué · A place to think, build, and understand.</span><a href="index.html">Compare the three directions ${arrow}</a></footer><div class="preview-label">V2 DESIGN PROTOTYPE · ${esc(design)}</div>`;
}
function recent() {
  return `<div class="latest-head"><span class="eyebrow">Latest published</span><a href="${href('atlas')}">All notes →</a></div><div class="latest-notes">${latest.map((n,i) => `<a ${external(n)} href="${noteHref(n)}"><span class="index">0${i+1}</span><div><span class="micro">${label(n.topic)}</span><h3>${esc(n.title)}</h3></div><time>${date(n)}</time>${arrow}</a>`).join('')}</div>`;
}
function orbit() {
  return `<svg class="orbit" viewBox="0 0 520 470" role="img" aria-label="Conceptual illustration of connections between research topics, not a computed note graph"><g fill="none" stroke="currentColor"><ellipse cx="260" cy="225" rx="205" ry="98" transform="rotate(-34 260 225)"/><ellipse cx="260" cy="225" rx="205" ry="98" transform="rotate(34 260 225)"/><ellipse cx="260" cy="225" rx="98" ry="205"/><circle cx="260" cy="225" r="54"/><path d="M260 20V430 M40 225H480" stroke-dasharray="2 8" opacity=".4"/></g><g fill="var(--accent)"><circle cx="260" cy="225" r="7"/><circle cx="420" cy="122" r="5"/><circle cx="98" cy="322" r="5"/><circle cx="285" cy="35" r="5"/></g><g fill="currentColor" font-size="10" font-family="monospace"><text x="325" y="50">MODELS</text><text x="384" y="350">SYSTEMS</text><text x="25" y="120">INFORMATION</text><text x="230" y="455">A CONNECTED ATLAS</text></g></svg>`;
}
function projects() {
  const rows = [['MagNav','Learning to remove magnetic disturbances.','deep learning / signal processing','MagNav'],['Looped Transformer','Exploring computation through recurrent depth.','architecture / research','Looped-Transformer'],['SigReg Kernel','Taking regularization closer to the hardware.','GPU kernels / optimization','SigReg-Kernel']];
  return `<section id="projects" class="projects"><div class="section-heading"><div><span class="eyebrow">02 / Selected work</span><h2>Ideas, implemented.</h2></div><a href="https://github.com/naatyu" target="_blank" rel="noopener">GitHub ${arrow}</a></div><div class="project-grid">${rows.map((r,i) => `<a href="https://github.com/naatyu/${r[3]}" target="_blank" rel="noopener"><span class="micro">0${i+1} / ${r[2]}</span><h3>${r[0]}</h3><p>${r[1]}</p>${arrow}</a>`).join('')}</div></section><section class="publication"><span class="eyebrow">Published research · IEEE / 2023</span><a href="https://ieeexplore.ieee.org/document/10189964" target="_blank" rel="noopener"><h3>Neural Network Calibration of Airborne Magnetometers ${arrow}</h3></a><p>Nathan Laoué, Arnaud Lepers, Laure Deletraz, Charly Faure</p></section>`;
}
function home() {
  const hero = design === 'editorial' ? `<section class="hero editorial-hero"><span class="eyebrow">The personal atlas of Nathan Laoué</span><h1>Understanding<br>is a practice.</h1><div class="editorial-lead"><p>Field notes on artificial intelligence, the systems beneath it, and the ideas worth returning to.</p><a class="button" href="${href('atlas')}">Explore the Atlas →</a></div><div class="issue-stamp">VOL. 02<br>AN OPEN NOTEBOOK<br>EST. 2023</div></section>` : design === 'lab' ? `<section class="hero lab-hero"><div><span class="eyebrow">Nathan Laoué / The learning lab</span><h1>Break it down.<br><em>Figure it out.</em></h1><p>Models. Math. Machines. An open collection of things I'm learning and building.</p><a class="button" href="${href('atlas')}">Enter the Atlas →</a></div><a class="lab-feature" href="${href('note')}"><span class="micro">TRY AN EXPLAINER</span><div class="big-symbol">P<span>↔</span>Q</div><h2>What does a<br>wrong prediction cost?</h2><span>Play with entropy & cross-entropy →</span></a></section>` : `<section class="hero observatory-hero"><div><span class="eyebrow"><span class="status-dot"></span> An open research notebook / 02</span><h1>Curiosity,<br>with <em>depth.</em></h1><p>I'm Nathan. I explore how models learn, how systems scale, and how ideas become working code.</p><a class="button" href="${href('atlas')}">Explore the Atlas →</a><span class="hero-count">${notes.filter(n=>!n.prototype).length} source notes · always evolving</span></div><div class="hero-art">${orbit()}</div></section>`;
  return `${hero}<section class="home-notes">${recent()}</section><section class="feature-strip"><span class="eyebrow">01 / Explore an idea</span><a href="${href('note')}"><h2>One distribution.<br>Three ways to measure it.</h2><p>Move the probabilities. See why cross-entropy is entropy plus wasted bits.</p><span class="text-link">Open the interactive note →</span></a><div class="mini-bars" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div></section>${projects()}`;
}
function learningPage() {
  return `<div class="note-breadcrumb"><a href="${href('atlas')}">Atlas</a> / Mathematics / Information theory</div><div class="reader-layout"><aside class="reader-nav"><span class="eyebrow">In this note</span><a href="#intuition">01 · The question</a><a href="#experiment">02 · Try it yourself</a><a href="#mechanism">03 · The mechanism</a><a href="#limits">04 · Where it breaks</a><a href="#connections">05 · Keep exploring</a></aside><article class="learning-note"><header class="note-heading"><span class="eyebrow">A visual foundation / 6 minute read</span><h1>The cost of<br>being <em>wrong.</em></h1><p class="note-deck">Entropy, cross-entropy, and KL divergence share one story: how much information you need, and how much you waste.</p><div class="note-meta">Learning prototype · Based on existing Atlas notes · Binary distributions / bits</div></header><section id="intuition"><h2>A predictable coin carries less surprise.</h2><p>If a coin almost always lands heads, tails tells you more than heads does. Information theory makes that intuition precise: an outcome with probability <code>p</code> carries <code>−log₂(p)</code> bits of surprise.</p><p>Now imagine predicting the coin using the wrong probabilities. You pay for the real uncertainty <strong>plus</strong> the mismatch. The experiment below separates those two costs.</p></section><section id="experiment" class="experiment"><div class="experiment-head"><span class="eyebrow">02 / Probability playground</span><span class="micro">CONCEPTUAL · NOT EMPIRICAL DATA</span></div><h2>Reality and your prediction.</h2><p>Move either slider. <strong>P</strong> describes the real coin; <strong>Q</strong> describes your prediction of that same coin. Tails has the remaining probability.</p><div class="control-grid"><label for="p-slider">Reality: P(heads) <output id="p-value">0.50</output><input id="p-slider" type="range" min="1" max="99" value="50"><span>More tails ← → More heads</span></label><label for="q-slider">Prediction: Q(heads) <output id="q-value">0.80</output><input id="q-slider" type="range" min="1" max="99" value="80"><span>More tails ← → More heads</span></label></div><div class="preset-row"><button data-preset="50,50">Fair & matched</button><button data-preset="90,90">Predictable & matched</button><button data-preset="90,10">Confident & wrong</button></div><div class="distribution-chart"><div><span>Reality / P</span><div class="probability-bar"><span id="p-heads"></span><span id="p-tails"></span></div></div><div><span>Prediction / Q</span><div class="probability-bar"><span id="q-heads"></span><span id="q-tails"></span></div></div></div><div class="metric-grid"><div><span>Unavoidable information</span><strong id="entropy">1.000</strong><span>H(P) · bits / outcome</span></div><div><span>Cost of the mismatch</span><strong id="kl">0.322</strong><span>KL(P ‖ Q) · bits / outcome</span></div><div><span>Total expected cost</span><strong id="cross">1.322</strong><span>H(P,Q) · bits / outcome</span></div></div><div class="decomposition" aria-label="Cross-entropy decomposed into entropy and KL divergence"><div id="entropy-part">Entropy</div><div id="kl-part">Mismatch</div></div><p id="experiment-insight" class="insight" aria-live="polite"></p><details><summary>Check the calculation, outcome by outcome</summary><table><caption>Expectation uses the true distribution P</caption><thead><tr><th>Outcome</th><th>P</th><th>Q</th><th>Ideal surprise</th><th>Predicted surprise</th></tr></thead><tbody id="calculation"></tbody></table></details></section><section id="mechanism"><span class="eyebrow">03 / The mechanism</span><h2>The mismatch is the extra cost.</h2><div class="equation">H(P, Q) = H(P) + KL(P ‖ Q)</div><div class="definition-grid"><div><h3>Entropy</h3><p>Average surprise when reality is described using its own probabilities.</p><code>H(P) = −Σ P(i) log₂ P(i)</code></div><div><h3>Cross-entropy</h3><p>Average surprise under P when the probabilities used to describe outcomes come from Q.</p><code>H(P,Q) = −Σ P(i) log₂ Q(i)</code></div><div><h3>KL divergence</h3><p>The expected excess over the best-matched description. It is nonnegative and asymmetric.</p><code>KL(P‖Q) = Σ P(i) log₂(P(i)/Q(i))</code></div></div><p>Subtract the first expectation from the second: <code>−log₂ Q(i) + log₂ P(i) = log₂(P(i)/Q(i))</code>. Weight by P and sum. That is why the identity holds.</p></section><section id="limits"><span class="eyebrow">04 / Boundaries</span><h2>“Impossible” is an expensive prediction.</h2><p>If Q assigns zero probability to an outcome that P can produce, cross-entropy and KL diverge to infinity. The sliders stop at 1% and 99% to keep this example finite.</p><p>The values describe ideal information lengths and expectations. They are not exact integer lengths for a one-symbol prefix code. The coding bound becomes meaningful through suitable coding schemes and repeated samples.</p><p>Changing log base changes the unit: base 2 gives bits; the natural logarithm gives nats. The identity remains the same.</p></section><section id="connections"><span class="eyebrow">05 / Connected concepts</span><h2>Take the idea further.</h2><div class="related-grid"><a href="https://naatyu.github.io/atlas/math/probability/entropy" target="_blank" rel="noopener">Entropy<span>Coding interpretation and derivation ↗</span></a><a href="https://naatyu.github.io/atlas/math/probability/kullback-leibler-divergence" target="_blank" rel="noopener">KL divergence<span>Asymmetry, regret, forward vs reverse ↗</span></a><a href="https://naatyu.github.io/atlas/ai/training/losses/cross-entropy-loss" target="_blank" rel="noopener">Cross-entropy loss<span>From information to model training ↗</span></a></div><p class="source-note">This is an original teaching prototype using exact binary-distribution calculations. It illustrates a possible consolidation; it does not replace the source notes or count as a completed migration.</p></section></article></div>`;
}
function review() {
  document.body.dataset.design='review';
  return `<main id="main" class="review-page"><span class="eyebrow">Nathan Laoué / Atlas v2</span><h1>Three ways<br>to see an idea.</h1><p class="review-lead">Same notes. Same interactive lesson. Different visual identities, layouts, and browsing experiences. Choose the world you want your Atlas to live in.</p><div class="review-grid">${[['observatory','01','Soft Observatory','A soft dark palette, restrained detail, and focused technical reading.'],['editorial','02','Light Studio','A calm light palette, generous space, and a product-like presentation.'],['lab','03','Learning Workspace','Cool, spacious surfaces and an explorer built for connected learning.']].map(([d,i,t,p])=>`<section class="direction ${d}"><a class="direction-preview" href="${href('home',d)}"><span>${i} / ${t}</span><h2>${d==='observatory'?'Curiosity,<br>with depth.':d==='editorial'?'Understanding<br>is a practice.':'Break it down.<br>Figure it out.'}</h2><span>Explore direction ↗</span></a><p>${p}</p><div class="review-links"><a href="${href('home',d)}">Homepage</a><a href="${href('atlas',d)}">Atlas</a><a href="${href('note',d)}">Interactive note</a></div></section>`).join('')}</div><p class="review-foot">${catalog.total} source documents inventoried · No production routes changed · Full editorial review pending</p></main>`;
}
const explorer=design&&view==='atlas'?finder({notes,esc,href,noteHref}):null;
if (!design) app.innerHTML = review();
else {
  document.body.dataset.design=design;
  const pageTitles={atlas:'The Atlas',note:'The cost of being wrong',moe:'Mixture of Experts',routing:'MoE routing',dfs:'Depth-first search'};
  document.title=`${pageTitles[view]||'Nathan Laoué'} · ${design}`;
  app.innerHTML=`${header()}<main id="main">${explorer?explorer.html:view==='moe'?moePage(href):view==='routing'?routingPage(href):view==='dfs'?dfsPage(href):view==='note'?learningPage():home()}</main>${footer()}`;
}
if (view==='atlas' && design) {
  explorer.mount();
  mountFinderNavigation({notes,esc,href,noteHref});
}
if(view==='dfs'&&design)mountDfs();
if (view==='note' && design) {
  const update=()=>{
    const p=Number(document.querySelector('#p-slider').value)/100,q=Number(document.querySelector('#q-slider').value)/100;
    const h=-p*Math.log2(p)-(1-p)*Math.log2(1-p),cross=-p*Math.log2(q)-(1-p)*Math.log2(1-q),kl=Math.max(0,cross-h);
    document.querySelector('#p-value').textContent=p.toFixed(2);document.querySelector('#q-value').textContent=q.toFixed(2);
    for (const [key,value] of [['entropy',h],['cross',cross],['kl',kl]]) document.querySelector(`#${key}`).textContent=value.toFixed(3);
    for (const [key,value] of [['p',p],['q',q]]) {const heads=document.querySelector(`#${key}-heads`),tails=document.querySelector(`#${key}-tails`);heads.style.flex=String(value);tails.style.flex=String(1-value);heads.textContent=`H ${Math.round(value*100)}%`;tails.textContent=`T ${Math.round((1-value)*100)}%`;}
    document.querySelector('#entropy-part').style.flex=String(h);document.querySelector('#kl-part').style.flex=String(kl);document.querySelector('#kl-part').style.display=kl<1e-8?'none':'flex';
    document.querySelector('#experiment-insight').textContent=kl<1e-8?`P and Q match. The extra cost is zero; all ${h.toFixed(3)} bits come from the coin's actual uncertainty.`:`The coin itself needs ${h.toFixed(3)} bits per outcome. Your prediction adds ${kl.toFixed(3)} wasted bits, for ${cross.toFixed(3)} bits in total.`;
    document.querySelector('#calculation').innerHTML=[['Heads',p,q],['Tails',1-p,1-q]].map(([name,a,b])=>`<tr><td>${name}</td><td>${a.toFixed(2)}</td><td>${b.toFixed(2)}</td><td>${(-Math.log2(a)).toFixed(3)} bits</td><td>${(-Math.log2(b)).toFixed(3)} bits</td></tr>`).join('');
  };
  document.querySelectorAll('input[type="range"]').forEach(input=>input.addEventListener('input',update));
  document.querySelectorAll('[data-preset]').forEach(b=>b.addEventListener('click',()=>{const [p,q]=b.dataset.preset.split(',');document.querySelector('#p-slider').value=p;document.querySelector('#q-slider').value=q;update();}));update();
}
const dialog=document.querySelector('#search-dialog');
const globalSearch=document.querySelector('#global-search');
function searchGlobal() {
  const q=globalSearch.value.toLowerCase();
  const matches=rank(notes,q).slice(0,12).map(result=>result.note);
  document.querySelector('#global-results').innerHTML=matches.map(n=>`<a ${external(n)} href="${previewViews[n.slug]?href(previewViews[n.slug],design||'editorial'):`https://naatyu.github.io${n.route}`}"><span>${esc(n.title)}</span><small>${label(n.topic)}</small></a>`).join('') || '<p>No results. Try a different concept.</p>';
}
function openSearch() {dialog.showModal();globalSearch.focus();searchGlobal();}
document.querySelectorAll('[data-search]').forEach(b=>b.addEventListener('click',openSearch));
document.querySelector('#close-search').addEventListener('click',()=>dialog.close());
globalSearch.addEventListener('input',searchGlobal);
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(dialog.open)dialog.close();else openSearch();}});
// Content is inserted after catalog loading, so restore deep-linked sections explicitly.
if (location.hash) document.getElementById(decodeURIComponent(location.hash.slice(1)))?.scrollIntoView();
